import DictionaryBrowser from '../../src/features/dictionary/DictionaryBrowser';
import React,{StrictMode,useState} from 'react';import {createRoot} from 'react-dom/client';import {IndexedDBAdapter} from '../../src/infrastructure/storage/IndexedDBAdapter';import {LanguageProvider} from '../../src/lib/LanguageContext';import ScheduledStudySession from '../../src/features/study/components/ScheduledStudySession';import StudyPreferences from '../../src/features/study/components/StudyPreferences';
const storage=new IndexedDBAdapter();await storage.init();storage.setWorkspaceOwner('reading-account');const repo=storage.getStudyRepository();let pages=await storage.listPages();let deck=pages.find(p=>p.title==='Reading');if(!deck){deck=await storage.createPage({title:'Reading',kind:'study_set'});await repo.ensureDeck(deck);await repo.addCards(deck.id,[{front:new URLSearchParams(location.search).get('case')==='chinese'?'中文題目':'preview',back:'預覽',...(new URLSearchParams(location.search).get('case')==='unlinked'?{}:{dictionary_entry_id:'00000000-0000-4000-8000-000000000001'})},{front:'review',back:'複習'}]);await repo.configure(deck.id,{direction_confirmed:true});
// Reading regressions pin a known initial batch; production now samples new cards randomly.
const originalRandom=Math.random;try{Math.random=()=>0;await repo.startSession(deck.id,'scheduled');}finally{Math.random=originalRandom;}}window.readingRepo=repo;window.readingDeck=deck.id;
function App(){const[view,setView]=useState('session'),[style,setStyle]=useState(null),[revision,setRevision]=useState(0);React.useEffect(()=>{const load=()=>repo.styleForDeck(deck.id).then(s=>setStyle(s.style));load();window.addEventListener('nexus-study-changed',load);return()=>window.removeEventListener('nexus-study-changed',load);},[]);return <LanguageProvider initialLanguage="zh-TW"><button onClick={()=>setView('session')}>Session</button><button onClick={()=>setView('manage')}>Manage</button><button onClick={()=>setView('closed')}>Close</button><button onClick={()=>setRevision(n=>n+1)}>Rerender {revision}</button>{style&&view==='session'&&<ScheduledStudySession repository={repo} deckId={deck.id} readingStyle={style} onExit={()=>setView('closed')}/>} {style&&view==='manage'&&<StudyPreferences repository={repo} deckId={deck.id} registerFlush={()=>{}}/>}</LanguageProvider>;}createRoot(document.getElementById('root')).render(<StrictMode>{new URLSearchParams(location.search).get('case')==='standalone'?<LanguageProvider initialLanguage="zh-TW"><DictionaryBrowser path={[]}/></LanguageProvider>:<App/>}</StrictMode>);
